import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Basic alphanumeric check on userId
        if (!userId.matches("[a-zA-Z0-9_]+")) {
            resp.sendError(400, "Invalid user id format");
            return;
        }

        // fields parameter allows caller to select columns
        // Default to safe set if not provided
        String columnList = "username, email, display_name";
        if (fields != null && !fields.isEmpty()) {
            // Attempt to sanitize: remove semicolons and comments
            fields = fields.replace(";", "").replace("--", "").replace("/*", "");
            columnList = fields;
        }

        String query = "SELECT " + columnList + " FROM user_profiles WHERE user_id = '" + userId + "'";
        logger.info("Executing query for user: " + userId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");

            ResultSetMetaData meta = rs.getMetaData();
            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                }
            }
            out.print("}");
            out.flush();
        } catch (SQLException e) {
            logger.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Update display name
        String userId = req.getParameter("id");
        String newName = req.getParameter("display_name");

        if (userId == null || !userId.matches("[a-zA-Z0-9_]+")) {
            resp.sendError(400, "Invalid user id");
            return;
        }
        if (newName == null || newName.length() > 100) {
            resp.sendError(400, "Invalid display name");
            return;
        }

        String update = "UPDATE user_profiles SET display_name = '" + newName.replace("'", "''") + "' WHERE user_id = '" + userId + "'";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            int rows = stmt.executeUpdate(update);
            resp.setContentType("application/json");
            resp.getWriter().print("{\"updated\":" + rows + "}");
        } catch (SQLException e) {
            logger.warning("Update error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    private String escapeJson(String val) {
        if (val == null) return "null";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
